import{_ as t,o,c as a,ag as r}from"./chunks/framework.44aEvdQQ.js";const f=JSON.parse('{"title":"Reframing Ownership - The Wealth Generator","description":"","frontmatter":{"title":"Reframing Ownership - The Wealth Generator","order":4},"headers":[],"relativePath":"about/chapters/04-reframing-ownership-the-wealth-generator.md","filePath":"about/chapters/04-reframing-ownership-the-wealth-generator.md"}'),s={name:"about/chapters/04-reframing-ownership-the-wealth-generator.md"};function n(i,e,h,u,l,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h4 id="business-as-asset-that-shouldn-t-require-you-to-do-the-work" tabindex="-1">Business as asset that shouldn&#39;t require you to do the work <a class="header-anchor" href="#business-as-asset-that-shouldn-t-require-you-to-do-the-work" aria-label="Permalink to &quot;Business as asset that shouldn&#39;t require you to do the work&quot;">​</a></h4><p>If you&#39;re reading this it&#39;s because you&#39;re looking for ways to improve the health of your small business. You have the power to change its course but you&#39;re concerned about heading in the wrong direction (you have to look your staff in the eyes every day). You feel the walls closing in — sensing prospects demand ever-decreasing prices for your work, hearing your staff complain about the rising cost of living. By facing the truth — what you own is different from what you do — and deciding your operating values you can normalize making profit. By giving your people more exposure to the finances of your business you control the narrative many owners fear, that their employees feel taken advantage of. No healthy business ignores the need to sell their offering for more than they pay to produce it, and your employees need to hear from you that you&#39;re all here to make profit. When your team understands the simple mechanics for showing up, many fringe benefits compound to reduce the load on your shoulders, chiefly the shift from <em>&quot;I am the business&quot;</em> to <em>&quot;I own a wealth-generating machine.&quot;</em> Success should look like a clean separation of roles and a team that has access to the levers they need to do a good job. This is a new thought for many small business owners because they surround themselves with other owners, who distrust their staff and feel a need to smother every decision with their approval. By prioritizing the mid- and long-term improvement of team standards you can alleviate the pressure on what you <em>do</em> and finally enjoy what you <em>own</em>. After all, you&#39;ve taken the <em>risk</em>.</p>',2)])])}const c=t(s,[["render",n]]);export{f as __pageData,c as default};
